"""Run after restarting the isolated browser fixture to check retained data and themes."""
import json,sys
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
root=Path(sys.argv[1]);info=json.load(open(root/'browser-info.json'));base=info['url'];errors=[]
with sync_playwright() as p:
 b=p.chromium.launch(headless=True);c=b.new_context(viewport={'width':1440,'height':1000},reduced_motion='reduce');page=c.new_page();page.on('pageerror',lambda e:errors.append(str(e)));assert c.request.post(base+'/account/login',headers={'origin':base},data={'username':'webhook-test','password':'isolated-browser-test-only-2026'}).ok;page.goto(base+'/webhook-workbench');page.wait_for_load_state('networkidle');page.get_by_role('button',name='Compute',exact=False).click();expect(page.locator('#detail')).to_contain_text('验收通过');expect(page.locator('#metrics')).to_contain_text('近期待投递')
 page.screenshot(path=str(root/'desktop-final.png'),full_page=True);page.evaluate("document.documentElement.dataset.theme='dark'");assert page.locator('body').evaluate("e=>getComputedStyle(e).backgroundColor")=='rgb(23, 24, 23)';page.screenshot(path=str(root/'dark-final.png'),full_page=True);page.emulate_media(color_scheme='dark');page.evaluate("document.documentElement.dataset.theme='light'");assert page.locator('body').evaluate("e=>getComputedStyle(e).backgroundColor")=='rgb(248, 248, 247)';page.set_viewport_size({'width':390,'height':844});assert page.evaluate('document.documentElement.scrollWidth <= window.innerWidth');page.screenshot(path=str(root/'mobile-final.png'),full_page=True);assert not errors;proof={'ok':True,'hostRestartPersistence':True,'finalDesktopAndMobile':True,'explicitThemeOverridesSystemTheme':True,'consoleErrors':errors};(root/'browser-final-delta.json').write_text(json.dumps(proof,indent=2));print(json.dumps(proof));b.close()
